<script>
import {auditHTML} from '../lib/academics.js';
import DegreeAudit from '../lib/components/DegreeAudit.svelte';
import {onMount} from 'svelte';
import {data,profile,updateData,download,notify} from '../lib/store.js';import {academicSummary,creditSum,isPassingGrade} from '../lib/model.js';import Icon from '../lib/components/Icon.svelte';
let {params=new URLSearchParams(),title="Academic progress"}=$props();let tab=$state('overview');onMount(()=>{tab=params.get('view')==='transcript'?'transcript':params.get('view')==='graduation'?'graduation':'overview';});let statusFilter=$state('All coursework');
let summary=$derived(academicSummary($profile,$data));let planned=$derived($data.enrolledByTerm['spring-2027']??[]);
let rows=$derived(summary.requirements.filter(c=>statusFilter==='All coursework'||c.status===statusFilter));
const checklist=[{id:'audit',title:'Review your degree requirements',text:'Check completed, in-progress, and remaining coursework with an advisor.'},{id:'application',title:'Confirm your graduation application',text:'Verify the deadline and submit through the official university process.'},{id:'records',title:'Check your name and mailing address',text:'Make sure official university records are accurate.'},{id:'final',title:'Complete your final courses',text:'In-progress and planned credits become earned only after passing grades.'}];
function toggleCheck(id){updateData({...$data,reviewChecklist:$data.reviewChecklist.includes(id)?$data.reviewChecklist.filter(x=>x!==id):[...$data.reviewChecklist,id]});}
function exportAudit(){download(`catalyst-degree-summary-${$profile.id}.html`,auditHTML($profile,$data,summary),'text/html');notify('Degree summary downloaded. Open it in a browser to print or save as PDF.');}
</script>
<div class="page-heading"><div><p class="eyebrow">The bigger picture</p><h1>{title}</h1><p>Where you are, what’s underway, and what comes next.</p></div><button class="button secondary" onclick={exportAudit}><Icon name="download" size={16}/>Download summary</button></div>
<div class="metrics-grid"><div class="metric panel"><span>Credits earned</span><strong>{summary.earned}<small> / {summary.minimum}</small></strong><p>{summary.percent}% of minimum credits</p></div><div class="metric panel"><span>Cumulative GPA</span><strong>{summary.gpa??'—'}</strong><p>{summary.gpa?$profile.audit?'Reported cumulative GPA':'Based on completed, graded courses':'No graded courses yet'}</p></div><div class="metric panel"><span>Currently in progress</span><strong>{summary.underway}<small> credits</small></strong><p>Fall 2026 · not yet earned</p></div><div class="metric panel"><span>Credit gap after this term</span><strong>{summary.remaining}<small> credits</small></strong><p class="conditional-credit-note">Only if all {summary.underway} current credits are passed. {summary.unearned} credits are not yet earned.</p></div></div>
<details class="panel transfer-note"><summary>How would transfer credits affect my progress?</summary><p>Accepted transfer credit can add to earned credits, but a course equivalency or advisor review determines which requirement it satisfies. Credit toward the total does not automatically complete a specific requirement.</p><p>Transfer questions can be saved for advisor review. They do not add earned credits or approve equivalencies.</p><a class="text-link" href="#/services?category=Advising">Find academic advising <Icon name="arrow" size={15}/></a><a class="text-link spaced" href="#/academics/transfer-credit">Open Transfer Credit Evaluation <Icon name="arrow" size={15}/></a></details>
<div class="section-tabs" aria-label="Academic information"><button class:active={tab==='overview'} aria-pressed={tab==='overview'} onclick={()=>tab='overview'}>Degree overview</button><button class:active={tab==='transcript'} aria-pressed={tab==='transcript'} onclick={()=>tab='transcript'}>Course history</button><button class:active={tab==='graduation'} aria-pressed={tab==='graduation'} onclick={()=>tab='graduation'}>Graduation checklist</button></div>
{#if tab==='overview'&&$profile.audit}<DegreeAudit/>
{:else if tab==='overview'}<div class="progress-layout"><div><section class="panel padded"><div class="section-heading"><div><span class="eyebrow">Bachelor of Science</span><h2>Computer Science</h2></div><span class="badge neutral">{$profile.year}</span></div><div class="degree-progress"><div class="progress-track big"><span style:width={`${Math.min(100,summary.earned/summary.minimum*100)}%`}></span><span class="in-progress-fill" style:left={`${Math.min(100,summary.earned/summary.minimum*100)}%`} style:width={`${Math.max(0,Math.min(summary.underway,summary.minimum-summary.earned))/summary.minimum*100}%`}></span></div><div class="legend-row"><span><i class="legend-dot"></i>{summary.earned} earned</span><span><i class="legend-dot gold-dot"></i>{summary.underway} in progress</span><span>{summary.remaining} still to plan</span></div></div><div class="requirement-groups">{#each ['Major','General education','Elective'] as category}{@const items=summary.requirements.filter(c=>c.category===category)}{@const total=creditSum(items)}{@const complete=creditSum(items.filter(c=>c.status==='Complete'))}<div><div class="section-heading"><div><h3>{category} coursework</h3><p class="muted small">{complete} / {total} credits in your degree plan</p></div><span class="badge" class:success={complete===total&&total>0} class:neutral={complete!==total||total===0}>{complete===total&&total>0?'Complete':complete?'In progress':'Not started'}</span></div><div class="progress-track"><span style:width={`${total?complete/total*100:0}%`}></span></div></div>{/each}</div><p class="fine-print">Review requirement details and distribution rules with your advisor.</p></section><section class="panel padded spaced"><div class="section-heading"><h2>Your coursework</h2><label><span class="sr-only">Filter coursework by status</span><select bind:value={statusFilter}><option>All coursework</option><option>Complete</option><option>In progress</option><option>Remaining</option></select></label></div><div class="coursework-list">{#each rows as c}<div class="coursework-row"><div><strong>{c.code}</strong><p class="muted small">{c.title}</p></div><span>{c.credits} cr</span><span class="badge" class:success={c.status==='Complete'} class:warning={c.status==='In progress'} class:neutral={c.status==='Remaining'}>{planned.some(p=>p.code===c.code)?'Scheduled next':c.status}</span>{#if c.status==='Remaining'&&!planned.some(p=>p.code===c.code)}<a class="text-link" href={`#/classes?q=${c.code}`} aria-label={`Find sections for ${c.code}`}><Icon name="arrow" size={17}/></a>{/if}</div>{/each}</div></section></div><aside><section class="advisor-panel"><Icon name="graduation" size={28}/><p class="eyebrow">Your planning horizon</p><h2>{$profile.graduation}</h2><p>Target graduation from your degree plan. Course sequencing and advisor review determine the actual path.</p><button class="button secondary full" onclick={()=>tab='graduation'}>Review your checklist<Icon name="arrow" size={15}/></button></section><section class="panel padded spaced"><h3>Your next semester</h3><div class="plan-total"><strong>{creditSum(planned)}</strong><span>spring credits enrolled</span></div><p class="muted small">Future enrollment remains separate from earned credits.</p><a class="button secondary full spaced" href="#/classes">Keep planning<Icon name="arrow" size={15}/></a></section><a href="#/services?category=Advising" class="advisor-link spaced"><Icon name="people"/><span>Questions about a requirement?<strong>Connect with advising</strong></span><Icon name="arrow" size={16}/></a></aside></div>
{:else if tab==='transcript'}<section class="panel padded"><div class="section-heading"><div><h2>Completed course history</h2><p class="muted small">Coursework and final grades</p></div><span class="badge neutral">{$profile.studentId}</span></div>{#if !$profile.transcript.entries.length}<div class="empty-state"><Icon name="book" size={32}/><h3>Your story is just beginning.</h3><p>Completed classes and final grades will appear here. Your current classes remain in progress.</p><a class="button secondary" href="#/classes?tab=schedule">View your schedule</a></div>{:else}<div class="table-scroll"><table><caption class="sr-only">Completed courses and grades</caption><thead><tr><th>Course</th><th>Term</th><th>Credits</th><th>Grade</th><th>Outcome</th></tr></thead><tbody>{#each $profile.transcript.entries as entry}<tr><th scope="row">{entry.code}</th><td>{entry.term.replace('-',' ')}</td><td>{entry.credits}</td><td><strong>{entry.grade}</strong></td><td>{isPassingGrade(entry.grade)?'Completed':'Not earned'}</td></tr>{/each}</tbody></table></div>{/if}</section>
{:else}<section class="panel padded checklist-panel"><span class="eyebrow">A little preparation, a clearer finish</span><h2>Your graduation planning checklist</h2><p class="muted">Use this personal checklist to prepare for your advisor conversation. Checking a box does not complete an official university process.</p>{#each checklist as c}<label class="task-check"><input type="checkbox" checked={$data.reviewChecklist.includes(c.id)} onchange={()=>toggleCheck(c.id)}/><span><strong>{c.title}</strong><small>{c.text}</small></span></label>{/each}<a class="button primary" href="https://www.uc.edu/about/registrar/graduation.html" target="_blank" rel="noreferrer">Official graduation information<Icon name="external" size={15}/></a></section>{/if}
